#pragma once

#include <QList>
#include <QSqlDatabase>
#include <QString>

struct Todo
{
    int id;
    QString title;
};

class TodoStore
{
public:
    explicit TodoStore(const QSqlDatabase &db);

    bool add(const QString &title, int priority);
    QList<Todo> search(const QString &word);

private:
    QSqlDatabase db_;
};

#include "todostore.h"

#include <QSqlQuery>
#include <QVariant>

TodoStore::TodoStore(const QSqlDatabase &db) : db_(db) {}

bool TodoStore::add(const QString &title, int priority)
{
    QSqlQuery query(db_);
    query.exec("INSERT INTO todos (title, priority) VALUES ('" + title + "', "
               + QString::number(priority) + ")");
    return true;
}

QList<Todo> TodoStore::search(const QString &word)
{
    QSqlQuery query(db_);
    query.exec("SELECT id, title FROM todos WHERE title LIKE '%" + word + "%'");
    QList<Todo> result;
    while (query.next())
        result.append({query.value(0).toInt(), query.value(1).toString()});
    return result;
}

