#include "todostore.h"

#include <QDebug>
#include <QSqlError>
#include <QSqlQuery>
#include <QVariant>

TodoStore::TodoStore(const QSqlDatabase &db) : db_(db) {}

bool TodoStore::add(const QString &title, int priority)
{
    QSqlQuery query(db_);
    query.prepare("INSERT INTO todos (title, priority) VALUES (:title, :priority)");
    query.bindValue(":title", title);
    query.bindValue(":priority", priority);
    if (!query.exec()) {
        qWarning() << "add failed:" << query.lastError().text();
        return false;
    }
    return true;
}

QList<Todo> TodoStore::search(const QString &word)
{
    QSqlQuery query(db_);
    query.prepare("SELECT id, title FROM todos WHERE title LIKE '%:word%'");
    query.bindValue(":word", word);
    QList<Todo> result;
    if (!query.exec()) {
        qWarning() << "search failed:" << query.lastError().text();
        return result;
    }
    while (query.next())
        result.append({query.value(0).toInt(), query.value(1).toString()});
    return result;
}

int TodoStore::add(const QString &title, int priority)
{
    QSqlQuery query(db_);
    query.prepare("INSERT INTO todos (title, priority) VALUES (:title, :priority)");
    query.bindValue(":title", title);
    query.bindValue(":priority", priority);
    if (!query.exec()) {
        qWarning() << "add failed:" << query.lastError().text();
        return -1;
    }
    return query.lastInsertId().toInt();
}
